toolArgs.file_text:
@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@notifications.Count</span></h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item">
                <strong>@n.Timestamp.ToString("HH:mm:ss")</strong> &mdash; @n.Message
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? Notifications { get; set; }

    private List<Notification> notifications => Notifications ?? new();

    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if not restored from prerender state
        Notifications ??= await NotificationSvc.GetNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Start polling only after the component is interactive (not during prerender)
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        var lastSeenId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;

        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(5000, ct).ConfigureAwait(false);

            if (ct.IsCancellationRequested)
                break;

            // Simulate a new notification arriving on some polls
            if (Random.Shared.Next(2) == 0)
            {
                NotificationSvc.SimulateIncoming();
            }

            var newer = await NotificationSvc.GetNotificationsSinceAsync(lastSeenId);
            if (newer.Count > 0)
            {
                lastSeenId = newer.Max(n => n.Id);
                await InvokeAsync(() =>
                {
                    Notifications!.InsertRange(0, newer);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

